function createLevenshteinDistance(a, b) {
  const matrix = [];

  for (let i = 0; i <= b.length; i++) {
    matrix[i] = [i];
  }

  for (let j = 0; j <= a.length; j++) {
    matrix[0][j] = j;
  }

  for (let i = 1; i <= b.length; i++) {
    for (let j = 1; j <= a.length; j++) {
      if (b.charAt(i - 1) === a.charAt(j - 1)) {
        matrix[i][j] = matrix[i - 1][j - 1];
      } else {
        matrix[i][j] = Math.min(
          matrix[i - 1][j - 1] + 1, // substitution
          matrix[i][j - 1] + 1,     // insertion
          matrix[i - 1][j] + 1      // deletion
        );
      }
    }
  }

  return matrix[b.length][a.length];
}

function getClosestMatch(propertyName, availableProperties) {
  let bestDistance = Infinity;
  let bestMatches = [];

  for (const prop of availableProperties) {
    const distance = createLevenshteinDistance(propertyName, prop);
    if (distance < bestDistance) {
      bestDistance = distance;
      bestMatches = [prop];
    } else if (distance === bestDistance) {
      bestMatches.push(prop);
    }
  }

  if (bestDistance > 3) {
    return null;
  }

  // Sort alphabetically and return the first one
  bestMatches.sort();
  return bestMatches[0];
}

function createDebugHelper(viewModel) {
  const availableProperties = Object.keys(viewModel).sort();

  function diagnoseMissingProperty(propertyName) {
    const isAvailable = availableProperties.includes(propertyName);

    const result = {
      error: true,
      missingProperty: propertyName,
      availableProperties: availableProperties,
      suggestion: isAvailable ? null : getClosestMatch(propertyName, availableProperties)
    };

    return result;
  }

  return {
    diagnoseMissingProperty: diagnoseMissingProperty
  };
}

module.exports = {
  createDebugHelper: createDebugHelper,
  // Also export Levenshtein helper for testing if needed
};
```

